664|size_t ZSTD_ldm_blockCompress(rawSeqStore_t* rawSeqStore,
665|    ZSTD_matchState_t* ms, seqStore_t* seqStore, U32 rep[ZSTD_REP_NUM],
666|    ZSTD_paramSwitch_e useRowMatchFinder,
667|    void const* src, size_t srcSize)
