670|    unsigned const minMatch = cParams->minMatch;
671|    ZSTD_blockCompressor const blockCompressor =
672|        ZSTD_selectBlockCompressor(cParams->strategy, useRowMatchFinder, ZSTD_matchState_dictMode(ms));
673|    /* Input bounds */
674|    BYTE const* const istart = (BYTE const*)src;
675|    BYTE const* const iend = istart + srcSize;
676|    /* Input positions */
677|    BYTE const* ip = istart;
678|
679|    DEBUGLOG(5, "ZSTD_ldm_blockCompress: srcSize=%zu", srcSize);
680|    /* If using opt parser, use LDMs only as candidates rather than always accepting them */
681|    if (cParams->strategy >= ZSTD_btopt) {
682|        size_t lastLLSize;
683|        ms->ldmSeqStore = rawSeqStore;
684|        lastLLSize = blockCompressor(ms, seqStore, rep, src, srcSize);
685|        ZSTD_ldm_skipRawSeqStoreBytes(rawSeqStore, srcSize);
686|        return lastLLSize;
687|    }
688|
689|    assert(rawSeqStore->pos <= rawSeqStore->size);
690|    assert(rawSeqStore->size <= rawSeqStore->capacity);
691|    /* Loop through each sequence and apply the block compressor to the literals */
692|    while (rawSeqStore->pos < rawSeqStore->size && ip < iend) {
693|        /* maybeSplitSequence updates rawSeqStore->pos */
694|        rawSeq const sequence = maybeSplitSequence(rawSeqStore,
695|                                                   (U32)(iend - ip), minMatch);
696|        int i;
697|        /* End signal */
698|        if (sequence.offset == 0)
699|            break;
700|
701|        assert(ip + sequence.litLength + sequence.matchLength <= iend);
702|
703|        /* Fill tables for block compressor */
704|        ZSTD_ldm_limitTableUpdate(ms, ip);
705|        ZSTD_ldm_fillFastTables(ms, ip);
706|        /* Run the block compressor */
707|        DEBUGLOG(5, "pos %u : calling block compressor on segment of size %u", (unsigned)(ip-istart), sequence.litLength);
708|        {
709|            size_t const newLitLength =
710|                blockCompressor(ms, seqStore, rep, ip, sequence.litLength);
711|            ip += sequence.litLength;
