6201|size_t ZSTD_compressStream2( ZSTD_CCtx* cctx,
6202|                             ZSTD_outBuffer* output,
6203|                             ZSTD_inBuffer* input,
6204|                             ZSTD_EndDirective endOp)
6205|{
6206|    DEBUGLOG(5, "ZSTD_compressStream2, endOp=%u ", (unsigned)endOp);
