6262|              || (endOp == ZSTD_e_end && flushMin == 0) ) { /* compression completed */
6263|                if (flushMin == 0)
6264|                    ZSTD_CCtx_trace(cctx, 0);
6265|                ZSTD_CCtx_reset(cctx, ZSTD_reset_session_only);
